import {esc,icon,download,formatDate} from './ui.mjs';
let deck,ctx,root,busy=false,dirty=false,selected=0,tab='upload',preview=0,controller,serviceMode='ai',pptTier='basic';
let presentationViewer=null,presentationViewerKey='';
let pptWorkflowProgress={},pptReading=false,pptExporting=false,pptResultView=null;
let presentationEpoch=0,jobPanel=null,autosaveTimer=null,presentationScoped=false,presentationRecovery=null;
export function disposePresentation(){presentationViewer?.dispose();presentationViewer=null;presentationViewerKey='';if(dirty)save(true);clearTimeout(autosaveTimer);jobPanel?.dispose();jobPanel=null;presentationRecovery=null;pptWorkflowProgress={};pptReading=false;pptExporting=false;pptResultView=null;presentationEpoch++;controller?.abort();controller=null;root=null;dirty=false;busy=false;}
const $=s=>root?.querySelector(s),defaultDeck=()=>({title:'',scenario:'通用汇报',projectId:'',degree:preferences().degree||'本科',minutes:10,pages:12,language:'中文',theme:'academic',author:'',school:'',advisor:'',material:'',fileName:'',prompt:'',notesMode:'concise',slides:[]});
export const presentationHasWork=()=>!!root?.querySelector('.ppt-grid,.ppt-mode-layout')&&(dirty||(busy&&!documentImportContinuesInBackground(root)));
export function presentationRouteGuard(){if(!root?.querySelector('.ppt-grid,.ppt-mode-layout'))return true;if(busy&&!documentImportContinuesInBackground(root)){ctx.notify('正在处理，请稍候。');return false;}if(dirty){save(true);if(dirty){ctx.notify('草稿暂未保存，请先导出备份再离开。');return false;}}return true;}
window.addEventListener('beforeunload',e=>{if(presentationHasWork()){e.preventDefault();e.returnValue='';}});
export function mountPresentation(context,draftId,projectId){disposePresentation();presentationScoped=hasDraftScope();controller=new AbortController();ctx=context;const routeParams=new URLSearchParams(String(location.hash).split('?')[1]||''),routeMode=routeParams.get('mode')||'ai',requestedJob=routeParams.get('job');const d=list(keys.drafts).find(d=>String(d.id)===String(draftId)&&d.tool==='ppt')||(!draftId&&requestedJob?list(keys.drafts).find(d=>d.tool==='ppt'&&d.presentation?.aiJob?.itemId===requestedJob):null)||(!draftId&&!requestedJob?recentSceneDraft(routeMode,projectId):null);deck=d?.presentation?structuredClone(d.presentation):defaultDeck();if(d){deck.id=d.id;deck.projectId=d.projectId||'';if(!d.presentation){deck.title=d.title;deck.material=d.text||'';deck.fileName='旧版演示提纲';}}else deck.projectId=projectId||'';const hash=String(location.hash||'');const mode=new URLSearchParams(hash.includes('?')?hash.split('?')[1]:'').get('mode');const savedMode=d?.presentation?.serviceMode;serviceMode=['ai','proposal','thesis'].includes(mode)?mode:['ai','proposal','thesis'].includes(savedMode)?savedMode:d?.presentation&&deck.scenario==='开题报告'?'proposal':d?.presentation&&deck.scenario==='毕业论文答辩'?'thesis':'ai';if(!d?.presentation||['ai','proposal','thesis'].includes(mode))deck.scenario=serviceMode==='proposal'?'开题报告':serviceMode==='thesis'?'毕业论文答辩':deck.scenario;pptTier=['basic','premium'].includes(d?.presentation?.pptTier)?d.presentation.pptTier:'basic';dirty=false;busy=false;selected=0;preview=0;tab=deck.material?'paste':'upload';root=document.querySelector('.dashboard');draw();root.addEventListener('click',actions,{signal:controller.signal});root.addEventListener('input',inputChange,{signal:controller.signal});root.addEventListener('change',inputChange,{signal:controller.signal});if(requestedJob&&!presentationScoped)void resumePresentationJob(requestedJob,presentationEpoch,!!d);}
const recentSceneDraft=(mode,projectId)=>list(keys.drafts).filter(row=>row.tool==='ppt'&&row.presentation?.autoSession&&row.presentation.serviceMode===mode&&(projectId===undefined||projectId===null||String(row.projectId||row.presentation.projectId||'')===String(projectId))).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)))[0];
const pptModes=[['ai','AI PPT','通用汇报','从主题与要求整理演示结构','AI'],['proposal','开题 PPT','开题汇报','讲清研究问题、方法与技术路线','PLAN'],['thesis','毕业 PPT','毕业答辩','呈现研究发现、结论与贡献','DEFENSE']];
const quickLabels=['论文答辩','开题报告','文献汇报','课题进展','学术会议','课程汇报','项目汇报','研究计划'];
function switchPresentationMode(mode){
 if(!['ai','proposal','thesis'].includes(mode)||mode===serviceMode)return true;
 if(!save(true)){ctx.notify('当前场景草稿暂未保存，请重试或导出备份后切换。');return false;}
 const projectId=deck.projectId,saved=recentSceneDraft(mode,projectId||'');
 // A scene keeps its own input, task and generated files. Never attach another scene's task to a fresh draft.
 presentationEpoch++;presentationRecovery=null;pptWorkflowProgress={};pptReading=false;pptExporting=false;pptResultView=null;deck=saved?{...defaultDeck(),...structuredClone(saved.presentation),id:saved.id,projectId:saved.projectId||saved.presentation.projectId||''}:{...defaultDeck(),projectId};
 if(deck.aiJob?.snapshot?.mode&&deck.aiJob.snapshot.mode!==mode){delete deck.aiJob;delete deck.generatedPresentation;}
 serviceMode=mode;deck.scenario=mode==='proposal'?'开题报告':mode==='thesis'?'毕业论文答辩':deck.scenario||'通用汇报';pptTier=['basic','premium'].includes(deck.pptTier)?deck.pptTier:'basic';selected=0;preview=0;tab=deck.material?'paste':'upload';
 const url=location.pathname+location.search+'#tool/ppt?'+new URLSearchParams({mode});window.history.replaceState(window.history.state,'',url);
 mark();save(true);draw();return true;
}
function pptModeIcon(mode,size=24){const paths={ai:'M3 4h18v12H3zM8 21l4-5 4 5M8 11V8M12 11V6M16 11V9',proposal:'M4 3h16v18H4zM8 7h8M8 11h4M8 16h2l2-3 2 4 2-2',thesis:'m2 9 10-5 10 5-10 5zM6 11v6c4 3 8 3 12 0v-6M22 9v8'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="${paths[mode]||paths.ai}"/></svg>`;}
function pptWorkflowState(){
 const hasInput=serviceMode==='ai'?!!(deck.prompt?.trim()||deck.material?.trim()):!!deck.material?.trim(),hasResult=!!deck.slides.length||!!presentationArtifact({presentation:deck.generatedPresentation});
 let changed=false,inputReady=false;try{const snapshot=presentationSnapshot(deck,serviceMode,pptTier);inputReady=true;if(deck.aiJob?.snapshot)changed=JSON.stringify(snapshot)!==JSON.stringify(deck.aiJob.snapshot);}catch{changed=!!deck.aiJob?.snapshot;}
 let phase='prepare',step=1;
 if(pptReading)phase='importing';
 else if(pptWorkflowProgress.auth==='changed')phase='blocked';
 else if(presentationRecovery?.status==='loading'){phase='recovering';step=3;}
 else if(pptWorkflowProgress.submitting||['queued','running'].includes(pptWorkflowProgress.status)){if(!pptWorkflowProgress.hasTask&&!inputReady){phase='checking';step=hasInput?2:1;}else{phase=!pptWorkflowProgress.hasTask?'preparing':pptWorkflowProgress.status==='queued'?'queued':'running';step=3;}}
 else if(changed){phase=hasInput?'review':'prepare';step=hasInput?2:1;}
 else if(pptWorkflowProgress.hasError){phase=pptWorkflowProgress.hasTask?'failed':'blocked_start';step=pptWorkflowProgress.hasTask?3:hasInput?2:1;}
 else if(['failed','cancelled'].includes(pptWorkflowProgress.status)){phase=pptWorkflowProgress.status;step=3;}
 else if(hasResult){phase=pptExporting?'exporting':'complete';step=4;}
 else if(pptWorkflowProgress.status==='completed'){phase='result_pending';step=3;}
 else if(pptWorkflowProgress.busy){phase='preparing';step=3;}
 else if(hasInput){phase='review';step=2;}
 const first=serviceMode==='ai'?'填写主题与要求':serviceMode==='proposal'?'导入开题报告':'导入论文材料';
 const hints={checking:'正在核对演示标题、资料与制作设置，请稍候。',prepare:serviceMode==='ai'?'先填写演示主题与制作要求，也可上传参考材料。':`先上传或粘贴${serviceMode==='proposal'?'开题报告':'论文'}正文，保留研究方法、数据与结论。`,importing:'正在读取参考材料，读取完成后可核对页数、语言与版式。',review:changed?'当前制作设置已更新，请核对后再生成；已保存的演示文稿仍保留。':'核对演示标题、页数与版式后，点击“AI 生成演示文稿”即可开始。',preparing:'正在核对制作资料并准备任务，请稍候，无需重复提交。',queued:'任务已提交，正在等待制作；完成后会自动展示演示文稿。',running:'正在制作演示文稿，具体进度会在任务区自动更新，无需重复点击生成。',recovering:'正在读取原任务与资料，原任务会保留，无需重复提交。',result_pending:'任务已结束，演示结果仍待核对与保存，请查看下方任务状态。',failed:'本次制作未完成，请查看任务区的具体原因；原稿与已保存版本仍保留。',cancelled:'本次制作已停止，原稿保留；可核对内容后继续制作。',blocked_start:'本次尚未开始制作，请查看任务区的具体原因，完成调整后再生成。',complete:'演示文稿已准备好。可在线预览、逐页核对与编辑，再下载 PPTX。',exporting:'正在导出演示文稿，请稍候。',blocked:'账户状态已变化，请重新进入本功能后继续。'};
 return {phase,step,hasInput,hasResult,hasTask:!!pptWorkflowProgress.hasTask,hint:hints[phase],steps:[[first,serviceMode==='ai'?'说明主题、听众与重点':'上传文档或核对材料正文'],['核对页数与版式','设置页数、语言与演示风格'],['AI 自动生成','制作进度自动更新'],['预览、编辑与下载','核对页面，导出 PPTX']]};
}
function pptJourney(){const state=pptWorkflowState();return `<nav class="ppt-journey tool-operation-workflow ppt-operation-workflow" data-ppt-workflow aria-label="${modeCopy[serviceMode].title}操作流程"><div class="tool-workflow-heading"><strong>操作流程</strong><span data-ppt-workflow-position></span></div><ol class="ppt-steps tool-workflow-steps">${state.steps.map(([title,detail],i)=>`<li><button type="button" data-ppt-workflow-step="${i+1}"><span data-ppt-workflow-number>${String(i+1).padStart(2,'0')}</span><div><b>${title}</b><small>${detail}</small></div></button></li>`).join('')}</ol><p class="tool-workflow-hint" data-ppt-workflow-hint></p></nav>`;}
function updatePptWorkflow(){
 const nav=$('[data-ppt-workflow]');if(!nav)return;const state=pptWorkflowState(),signature=JSON.stringify(state);if(nav.dataset.workflowState===signature)return;nav.dataset.workflowState=signature;nav.dataset.phase=state.phase;nav.dataset.currentStep=String(state.step);
 const version=$('[data-ppt-result-version]');if(version){version.hidden=!state.hasResult||!['prepare','review'].includes(state.phase);version.textContent='制作要求或设置已更新，下方保留的是上次结果；重新生成后会更新。';}
 nav.querySelector('[data-ppt-workflow-position]').textContent=`第 ${state.step} 步 / 共 4 步`;nav.querySelector('[data-ppt-workflow-hint]').textContent=state.hint;
 nav.querySelectorAll('[data-ppt-workflow-step]').forEach((button,i)=>{const active=i+1===state.step,done=i+1<state.step;button.classList.toggle('is-active',active);button.classList.toggle('is-completed',done);button.disabled=state.phase==='blocked'||(i===1?!state.hasInput:i===2?!state.hasTask&&state.step!==3:i===3?!state.hasResult:false);button.setAttribute('aria-label',`${i+1} ${state.steps[i][0]}${active?'，当前步骤':done?'，已完成':''}`);if(active)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');button.querySelector('[data-ppt-workflow-number]').textContent=done?'✓':String(i+1).padStart(2,'0');});
}

function pptStartSettings(){return `<div class="ppt-start-settings"><label>所属项目（可选）<select data-field="projectId" aria-label="所属项目" data-project-picker data-project-ref="${esc(deck.projectId||'')}">${projectPickerOptions(deck.projectId||'')}</select></label>${field('title','演示标题',deck.title,120)}<label>目标页数<input type="number" data-field="pages" aria-label="目标页数" min="6" max="30" value="${deck.pages}"></label><label>预计汇报时长（分钟）<input type="number" data-field="minutes" aria-label="汇报时长" min="1" max="120" value="${deck.minutes}"></label><label>演示语言<select data-field="language" aria-label="演示语言">${selectOptions(['中文','英文'],deck.language)}</select></label><label>学段<select data-field="degree" aria-label="学段">${selectOptions(['专科','本科','硕士','博士','科研人员'],deck.degree)}</select></label>${field('author','作者署名',deck.author,100)}${field('school','学校 / 单位',deck.school)}${field('advisor','指导教师',deck.advisor)}${notesSettings()}</div>`;}
function selectOptions(values,value){return values.map(v=>`<option ${String(v)===String(value)?'selected':''}>${esc(v)}</option>`).join('');}
function field(id,label,value,max=100){return `<label>${label}<input data-field="${id}" aria-label="${label}" maxlength="${max}" value="${esc(value)}"></label>`;}
function renderPresentationRecovery(){
 const state=presentationRecovery;if(!state)return;if(!state.current()){if(presentationRecovery===state)presentationRecovery=null;return;}updatePptWorkflow();const box=root?.querySelector('.ppt-ai-job');if(!box)return;box.hidden=false;
 if(state.status==='loading'){box.innerHTML='<p role="status">正在恢复本次演示任务与原始资料…</p>';return;}
 if(state.status==='error'){box.innerHTML='<p role="alert">任务暂不可恢复，请确认登录账户后从任务中心重试。原任务仍保留。</p><a class="btn secondary" href="#tasks?scope=account">打开账户任务中心</a>';return;}
 box.innerHTML='<p role="status">原任务已读取。你在等待期间编辑了当前资料，当前输入已保留。</p><p>恢复原任务前会先保存当前资料为独立草稿，不会覆盖这份输入。</p><button type="button" class="btn secondary" data-ppt-restore-job '+(state.busy?'disabled':'')+'>另存当前输入并恢复原任务</button><p data-ppt-recovery-error role="alert">'+esc(state.error||'')+'</p>';
 box.querySelector('[data-ppt-restore-job]').addEventListener('click',async()=>{if(presentationRecovery!==state||!state.current()||state.busy)return;state.busy=true;state.error='';renderPresentationRecovery();try{if(!save(true))throw Error('当前输入暂未保存，未恢复旧任务，请保留输入后重试。');await state.restore();}catch(error){if(presentationRecovery===state&&state.current()){state.busy=false;state.error=error.message;renderPresentationRecovery();}}});
}
async function resumePresentationJob(id,epoch,hasSaved){
 if(!/^[A-Za-z0-9_-]{1,160}$/.test(id))return ctx.notify('任务链接无效，请从账户任务中心重新打开。');
 const initial=JSON.stringify(deck),scope=captureDraftScope(),mounted=root,current=()=>epoch===presentationEpoch&&mounted===root&&mounted?.isConnected&&scope.isCurrent();
 try{
  if(hasSaved){await jobPanel.open();return;}
  presentationRecovery={status:'loading',current};renderPresentationRecovery();
  async function request(path){if(ctx.api)return ctx.api(path,undefined,{signal:controller.signal});const response=await fetch('/api'+path,{credentials:'same-origin',cache:'no-store',signal:controller.signal});const value=await response.json();if(!response.ok)throw Error(value.error||'任务暂不可读取。');return value;}
  const session=await request('/auth/me');if(!session.user?.id)throw Error('请登录任务所属账户后继续。');
  const {item}=await request('/tool-runs/jobs/'+encodeURIComponent(id));if(!current())return;
  if(item?.kind!=='presentation'||item?.operation!=='ppt'||item?.id!==id)throw Error('未找到这份演示任务，请在账户任务中心核对。');
  const restore=async()=>{if(!current())return;const before={deck,serviceMode,pptTier,dirty};try{deck=restorePresentationSnapshot(item.snapshot,defaultDeck());serviceMode=deck.serviceMode;pptTier=deck.pptTier;const snapshot=presentationSnapshot(deck,serviceMode,pptTier);deck.aiJob={itemId:id,ownerId:session.user.id,snapshot,contextKey:JSON.stringify(snapshot)};mark();if(!save(true))throw Error('任务资料暂未保存，请释放浏览器空间后重试。');presentationRecovery=null;draw();await jobPanel.open();}catch(error){deck=before.deck;serviceMode=before.serviceMode;pptTier=before.pptTier;dirty=before.dirty;throw error;}};
  if(JSON.stringify(deck)!==initial){
   presentationRecovery={status:'ready',current,restore,busy:false,error:''};renderPresentationRecovery();return;
  }
  await restore();
 }catch(error){if(current()&&error.name!=='AbortError'){ctx.notify(error.message||'任务暂不可恢复，请在账户任务中心重试。');presentationRecovery={status:'error',current};renderPresentationRecovery();}}
}
function generatedPresentation(){
 const artifact=presentationArtifact({presentation:deck.generatedPresentation});if(!artifact)return '';
 const files=presentationDownloads({presentation:deck.generatedPresentation}),primary=files.find(file=>file.role==='deck'),extras=files.filter(file=>file.role!=='deck');
 return `<section class="ppt-generated-file" aria-label="生成版演示文稿"><div class="ppt-generated-summary">${icon('file',24)}<div><span class="ppt-result-saved">生成版已保存到账户</span><h3>${esc(artifact.fileName)}</h3><p>${artifact.pageCount?artifact.pageCount+' 页 · ':''}可编辑 PPTX</p></div></div><div class="ppt-actions">${primary?`<button type="button" class="btn primary" data-action="download-generated" data-file-role="deck">${icon('file',16)} 下载生成版 PPTX</button>`:''}${extras.length?`<details class="ppt-result-more"><summary>更多下载</summary><div>${extras.map(file=>`<button type="button" class="btn secondary" data-action="download-generated" data-file-role="${file.role}">${file.label}</button>`).join('')}</div></details>`:''}</div></section><section data-ppt-generated-viewer></section><p class="ppt-generated-boundary">此预览对应上方生成版文件；逐页编辑不会更新这份生成版文件，可另行导出修改后的内容。</p>`;
}
function pptResultWorkspace(){
 const artifact=presentationArtifact({presentation:deck.generatedPresentation}),slides=deck.slides,hasResult=!!artifact||!!slides.length;
 if(!hasResult)return `<section class="ppt-result-workspace ppt-result-empty" id="ppt-result" aria-label="演示文稿结果"><span class="ppt-result-placeholder-icon">${icon('chart',28)}</span><div><h2>预览与下载</h2><p>生成完成后，在这里预览演示文稿、编辑逐页内容并下载 PPTX。</p></div></section>`;
 const view=artifact&&pptResultView!=='content'?'generated':'content';pptResultView=view;
 const show=slides[Math.min(preview,slides.length-1)],pageCount=artifact?.pageCount||slides.length;
 return `<section class="ppt-result-workspace" id="ppt-result" data-ppt-result-view="${view}" aria-label="演示文稿结果"><header class="ppt-result-heading"><div><span class="ppt-result-eyebrow">04 · 预览与交付</span><h2>${esc(deck.title||'演示文稿')}</h2><p>${pageCount} 页 · ${esc(deck.language||'中文')} · ${esc(modeCopy[serviceMode].title)}</p></div><a class="btn secondary" href="#assets?scope=account">${icon('folder',16)} 文件管理</a></header><p class="ppt-result-version-note" data-ppt-result-version hidden></p><div class="ppt-result-tabs" role="group" aria-label="查看演示文稿">${artifact?`<button type="button" data-ppt-result-view="generated" aria-pressed="${view==='generated'}">${icon('chart',16)} 生成版预览</button>`:''}${slides.length?`<button type="button" data-ppt-result-view="content" aria-pressed="${view==='content'}">${icon('pen',16)} 逐页编辑</button>`:''}<span>预览、编辑与下载集中在这里</span></div>${artifact?`<div data-ppt-result-panel="generated" ${view!=='generated'?'hidden':''}>${generatedPresentation()}</div>`:''}${slides.length?`<div data-ppt-result-panel="content" ${view!=='content'?'hidden':''}><p class="ppt-content-boundary">${artifact?'正在编辑逐页内容；导出时使用基础版式，生成版文件仍保留。':'核对逐页内容与备注，完成后导出可编辑 PPTX。'}</p><div class="ppt-content-grid"><aside class="ppt-page-navigation"><h2>演示页面</h2><div class="ppt-outline" data-scroll-key="ppt-outline-1">${slides.map((slide,i)=>`<button type="button" data-edit="${i}" aria-current="${selected===i?'page':'false'}"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(slide.title)}</b></button>`).join('')}</div></aside><div class="ppt-page-workbench"><div class="ppt-content-preview"><div class="ppt-content-preview-heading"><strong>编辑稿预览</strong><span>基础版式 · 第 ${Math.min(preview+1,slides.length)} / ${slides.length} 页</span></div><div class="ppt-tabs" data-scroll-key="ppt-tabs-2" role="group" aria-label="编辑稿版式">${Object.entries(themes).map(([id,t])=>`<button type="button" data-theme="${id}" aria-pressed="${deck.theme===id}" class="${deck.theme===id?'active':''}">${t.name}</button>`).join('')}</div><div id="ppt-live-preview">${slidePreview(show)}</div><div class="ppt-thumbnails">${slides.slice(0,3).map((slide,i)=>`<button type="button" data-preview="${i}" aria-pressed="${preview===i}" aria-label="预览编辑稿第 ${i+1} 页">${slidePreview(slide,true)}</button>`).join('')}</div></div>${editor()}</div></div></div>`:''}</section>`;
}
function showPptResultView(view){
 const result=$('#ppt-result');if(!result||!['generated','content'].includes(view)||!result.querySelector(`[data-ppt-result-panel="${view}"]`))return;
 pptResultView=view;result.dataset.pptResultView=view;result.querySelectorAll('[data-ppt-result-panel]').forEach(panel=>panel.hidden=panel.dataset.pptResultPanel!==view);result.querySelectorAll('button[data-ppt-result-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.pptResultView===view)));
}
