function inputChange(e){if(e.target.dataset.pptFilter){deck.templateFilters={...(deck.templateFilters||{}),[e.target.dataset.pptFilter]:e.target.value};mark();draw();return;}if(e.target.dataset.field){deck[e.target.dataset.field]=['pages','minutes'].includes(e.target.dataset.field)?Number(e.target.value):e.target.value;if(e.target.dataset.field==='notesMode')pptTier=deck.notesMode==='detailed'?'premium':'basic';mark();if(e.target.dataset.field==='material')$('#ppt-material-state').textContent=`${deck.fileName||'粘贴材料'} · ${deck.material.length.toLocaleString('zh-CN')} 字符`;jobPanel?.inputChanged?.();}if(e.target.dataset.slide){deck.slides[selected][e.target.dataset.slide]=e.target.value;mark();preview=selected;if($('#ppt-live-preview'))$('#ppt-live-preview').innerHTML=slidePreview(deck.slides[selected]);const entry=$(`[data-edit="${selected}"]`);if(entry)entry.innerHTML=`<span>${String(selected+1).padStart(2,'0')}</span>${esc(deck.slides[selected].title)}${icon('pen',14)}`;}if(e.target.id==='ppt-file')readFile(e.target.files[0]);}
function freeze(value){root?.querySelectorAll('input,textarea,select,button').forEach(el=>{if(value){el.dataset.pptDisabled=String(el.disabled);el.disabled=true;}else if(el.dataset.pptDisabled!==undefined){el.disabled=el.dataset.pptDisabled==='true';delete el.dataset.pptDisabled;}});}
function bindDrop(){const grid=root.querySelector('.ppt-grid');if(grid&&!root.querySelector('.ppt-mode-layout')&&!root.querySelector('.ppt-service-panel'))grid.insertAdjacentHTML('beforebegin',pptServicePanel());const drop=$('#ppt-drop');if(!drop)return;drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag');});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files.length!==1)return ctx.notify('每次请选择一份文件。');readFile(e.dataTransfer.files[0]);});}
async function readFile(file){const epoch=presentationEpoch;if(!file||busy)return;if(!/\.(docx|pdf|txt)$/i.test(file.name)||file.size>50*1024*1024)return ctx.notify('TXT / DOCX 最大 50MB；PDF 最大 20MB / 100 页。');if(deck.material&&!confirm('替换当前参考材料？已编辑的页面会保留，请重新核对。'))return;busy=true;pptReading=true;updatePptWorkflow();freeze(true);const mounted=root;const state=$('#ppt-material-state');if(state)state.textContent='正在准备文档解析…';try{if(epoch!==presentationEpoch)return;const r=await importWorkspaceDocument(file,state,{signal:controller.signal});if(epoch!==presentationEpoch)return;const text=validateMaterial(r.text);if(!mounted.isConnected)return;deck.material=text;deck.fileName=file.name;if(!deck.title)deck.title=file.name.replace(/\.[^.]+$/,'');mark();tab='paste';ctx.notify(r.warnings.length?'文件已解析，部分页面有解析提示，请核对正文。':'已解析正文，请核对。');}catch(e){if(epoch===presentationEpoch)ctx.notify(e.message||'文件解析失败。');}finally{if(epoch===presentationEpoch){busy=false;pptReading=false;if(mounted.isConnected)draw();}}}
export function savePresentationDraft(){if(!root)return false;save();return !dirty;}
function save(quiet=false){if(!deck||!root||presentationScoped!==hasDraftScope())return false;if(!deck.title.trim()&&!quiet)return ctx.notify('请填写演示标题。');try{const rows=list(keys.drafts),old=rows.find(d=>d.id===deck.id),now=new Date().toISOString(),id=deck.id||crypto.randomUUID();const saved={...old,id,title:deck.title.trim()||deck.prompt?.trim().slice(0,40)||'未命名演示草稿',tool:'ppt',kind:deck.slides.length?'演示文稿':'演示草稿',stage:deck.slides.length?'presentation':'draft',projectId:deck.projectId,createdAt:old?.createdAt||now,updatedAt:now,text:deckText(deck),presentation:structuredClone({...deck,id,serviceMode,pptTier,autoSession:true})};write(keys.drafts,old?rows.map(d=>d.id===id?saved:d):[saved,...rows]);deck.id=id;dirty=false;if(!quiet)try{recordTask({id:'draft-'+id,title:deck.title,kind:'本地演示保存',status:'completed',projectId:deck.projectId,url:'#draft/'+id});}catch{}if(!quiet){ctx.notify(presentationScoped?'编辑已暂存本页，请点击上方“保存到账户”。':'文稿已保存到当前浏览器。');draw();}else{const status=$('#ppt-status');if(status)status.textContent=presentationScoped?'编辑已暂存本页，请点击上方“保存到账户”。':'已自动保存到当前浏览器。';}return true;}catch{if(!quiet)ctx.notify('浏览器保存失败，请导出文稿备份。');return false;}}
function choose(){const rows=list(keys.drafts).filter(d=>d.tool!=='ppt'&&(d.text?.trim()||d.html));ctx.modal('选择已有成果',`<p class="hub-footnote">复制已有正文；大纲与模板不代表真实论文。</p>${rows.map(d=>`<button class="ppt-existing" data-ppt-existing="${esc(d.id)}"><b>${esc(d.title)}</b><small>${esc(d.kind||'创作成果')}</small></button>`).join('')||'<p>暂无可导入成果。</p>'}`);document.querySelectorAll('[data-ppt-existing]').forEach(b=>b.addEventListener('click',()=>{const d=rows.find(d=>String(d.id)===b.dataset.pptExisting);if(deck.material&&!confirm('替换当前参考材料？'))return;let text=d.text||'';if(!text&&d.html){const div=document.createElement('div');div.innerHTML=d.html;div.querySelectorAll('p,h3,h4').forEach(n=>n.append(document.createTextNode('\n')));text=div.textContent||'';}try{deck.material=validateMaterial(text);deck.title=d.title;deck.projectId=d.projectId||deck.projectId;deck.fileName='已有成果：'+d.title;tab='paste';mark();document.querySelector('#workspace-dialog').close();draw();}catch(e){ctx.notify(e.message);}}));}
async function actions(e){const epoch=presentationEpoch;const b=e.target.closest('button');if(!b)return;if(b.dataset.pptResultView){showPptResultView(b.dataset.pptResultView);return;}if(b.dataset.pptWorkflowStep){if(b.disabled)return;const step=Number(b.dataset.pptWorkflowStep),target=step===1?(serviceMode==='ai'?$('#ppt-brief,[data-field=prompt]'):$('#ppt-drop,[data-field=material]')):step===2?$('.ppt-template-gallery,[data-field=pages]'):step===3?$('.ppt-ai-job:not([hidden])')||$('[data-action=ai-generate]'):$('#ppt-result');target?.scrollIntoView?.({block:'center',behavior:'auto'});target?.focus?.({preventScroll:true});return;}if(busy)return ctx.notify('正在处理，请稍候。');if(b.dataset.pptMode){switchPresentationMode(b.dataset.pptMode);return;}if(b.dataset.pptTier){pptTier=b.dataset.pptTier;deck.notesMode=pptTier==='premium'?'detailed':'concise';mark();draw();return;}if(b.dataset.pptTemplatePreview){openTemplatePreview(b.dataset.pptTemplatePreview);return;}if(b.dataset.pptTemplate){deck.theme=Object.keys(themes)[Number(b.dataset.pptTemplate.split('-').pop())]||'academic';mark();draw();return;}if(b.dataset.pptQuick!==undefined){const labels=quickLabels;const label=labels[Number(b.dataset.pptQuick)];const nextMode=label==='开题报告'?'proposal':label==='论文答辩'?'thesis':serviceMode;if(nextMode!==serviceMode&&!switchPresentationMode(nextMode))return;if(!deck.title&&label)deck.title=label;if(serviceMode==='ai'&&!deck.prompt&&label)deck.prompt=`制作一份${label}演示文稿，按背景、核心内容、重点发现与总结组织结构。`;if(serviceMode!=='ai')deck.title=deck.title||modeCopy[serviceMode].title;mark();draw();return;}if(b.dataset.scenario){deck.scenario=b.dataset.scenario;mark();draw();return;}if(b.dataset.theme){deck.theme=b.dataset.theme;mark();draw();return;}if(b.dataset.source){tab=b.dataset.source;draw();if(tab==='existing')choose();return;}if(b.dataset.preview!==undefined){preview=Number(b.dataset.preview);selected=preview;pptResultView='content';draw();return;}if(b.dataset.edit!==undefined){selected=Number(b.dataset.edit);preview=selected;pptResultView='content';draw();return;}try{switch(b.dataset.action){case 'view-result':$('#ppt-result')?.scrollIntoView?.({block:'start',behavior:'auto'});break;case 'download-generated':await downloadGeneratedPresentation(epoch,b.dataset.fileRole||'deck');break;case 'ai-status':await jobPanel?.open();break;case 'ai-generate':if(presentationScoped)throw Error('账户草稿仅在内存编辑，请在独立 PPT 创作页生成后保存到账户。');await jobPanel.generate();break;case 'pick-file':$('#ppt-file')?.click();break;case 'choose':choose();break;case 'generate':if(!deck.title.trim())deck.title=serviceMode==='proposal'?'开题报告':serviceMode==='thesis'?'毕业论文答辩':'AI PPT';if(deck.slides.length&&!confirm('重新创建大纲将替换当前全部页面，请先保存或导出备份。确定继续？'))return;deck.slides=buildSlides({...deck,material:deck.material||deck.prompt||''});selected=0;preview=0;mark();draw();ctx.notify('已创建结构大纲，请逐页补充真实材料。');break;case 'restore-version':if(!deck.versions?.length)break;if(!confirm('恢复上次页面？当前页面会保留在备份中。'))break;{const previous=deck.versions.shift(),current=structuredClone(deck.slides);deck.slides=previous.slides;deck.versions.push({savedAt:new Date().toISOString(),slides:current});selected=0;preview=0;mark();draw();}break;case 'save':save();break;case 'add':if(deck.slides.length>=30)throw new Error('最多 30 页。');deck.slides.splice(selected+1,0,{id:crypto.randomUUID(),title:'新页面',body:'',notes:'',layout:'content'});selected++;preview=selected;mark();draw();break;case 'remove':if(!confirm('移除当前页并自动保存？删除前会保留一份页面备份，可恢复最近 5 次替换或删页。'))return;deck.versions=[{savedAt:new Date().toISOString(),label:'删除页面前',slides:structuredClone(deck.slides)},...(deck.versions||[])].slice(0,5);deck.slides.splice(selected,1);selected=Math.max(0,selected-1);preview=selected;mark();draw();break;case 'up':case 'down':{const next=selected+(b.dataset.action==='up'?-1:1);if(next<0||next>=deck.slides.length)return;[deck.slides[selected],deck.slides[next]]=[deck.slides[next],deck.slides[selected]];selected=next;preview=selected;mark();draw();break;}case 'export':busy=true;pptExporting=true;updatePptWorkflow();freeze(true);try{const exportScope=captureDraftScope(),snapshot=structuredClone(deck),current=()=>epoch===presentationEpoch&&exportScope.isCurrent()&&root?.isConnected;const {exportPresentation}=await import('./assets/presentation-export.js');if(!current())return;const bytes=await exportPresentation(snapshot);if(!current())return;await download((snapshot.title||'演示文稿')+'.pptx',bytes,'application/vnd.openxmlformats-officedocument.presentationml.presentation',{expectedUserId:exportScope.ownerId});if(!current())return;ctx.notify(deck.generatedPresentation?'已导出当前编辑内容的基础版式 PPTX，生成版文件仍单独保留。':'已导出 PPTX，请在 PowerPoint 中核对排版。');}finally{if(epoch===presentationEpoch){busy=false;pptExporting=false;freeze(false);updatePptWorkflow();}}break;case 'text':await download(deck.title+'.txt',deckText(deck));break;case 'json':await download((deck.title||'演示草稿')+'-PaperKnow.json',JSON.stringify(deck,null,2),'application/json');break;case 'print':validateDeck(deck);await download(deck.title+'-打印预览.html',printHtml(),'text/html');ctx.notify('已下载打印预览，打开后选择打印并保存 PDF。');break;}}catch(error){if(epoch===presentationEpoch)ctx.notify(error.message||'操作失败，请重试。');}}
function printHtml(){return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>${esc(deck.title)}</title><style>body{font-family:Arial,'Microsoft YaHei',sans-serif;margin:0;background:#eee}button{margin:20px;padding:12px}section{box-sizing:border-box;background:#fff;width:297mm;min-height:167mm;padding:22mm;page-break-after:always;border-left:4mm solid #${themes[deck.theme].accent}}h1{font-size:30pt;color:#${themes[deck.theme].dark}}p{font-size:20pt;white-space:pre-wrap;overflow-wrap:anywhere}.print-note{font-size:14px;margin:20px;line-height:1.8}@page{size:297mm 167mm;margin:0}@media print{button,.print-note{display:none}body{background:white}}</style><button onclick="window.print()">打印 / 保存 PDF</button><p class="print-note">这是当前编辑内容的基础打印预览。长正文会继续分页，打印页数可能多于演示页数；请在打印对话框核对分页。</p>${deck.slides.map(s=>`<section><small>PaperKnow · ${esc(deck.scenario)}</small><h1>${esc(s.title)}</h1>${s.layout==='cover'&&deck.author?'<small>作者：'+esc(deck.author)+'</small>':''}<p>${esc(s.body)}</p></section>`).join('')}</html>`;}
